$ErrorActionPreference='Stop'
Import-Module (Join-Path $PSScriptRoot 'Repato.MayaQaWorkflow.psm1') -Force -WarningAction SilentlyContinue
Import-Module (Join-Path $PSScriptRoot 'Repato.AgentOrchestration.psm1') -Force -WarningAction SilentlyContinue
Import-Module (Join-Path $PSScriptRoot 'Repato.Deployment.v4.psm1') -Force -WarningAction SilentlyContinue

$tempBase=[IO.Path]::GetFullPath([IO.Path]::GetTempPath())
$isolatedRoot=Join-Path $tempBase ('mps-'+[guid]::NewGuid().ToString('N').Substring(0,8))
$qaRuns=Join-Path $isolatedRoot 'TestRuns';$qaFixtures=Join-Path $isolatedRoot 'Fixtures';$prepRoot=Join-Path $qaRuns 'p';$qaRunRoot=$null
$workflowModule=Get-Module Repato.MayaQaWorkflow;& $workflowModule {param($root)$script:MayaQaRootOverrideForTests=$root} $isolatedRoot
$fixturePath=Join-Path $qaFixtures 'CreatePlanViewsEmpty.rvt'
$store=Join-Path $isolatedRoot 'store'
$files=Join-Path $isolatedRoot 'files'
New-Item -ItemType Directory -Path $files,$qaRuns,$qaFixtures -Force|Out-Null
[IO.File]::WriteAllBytes($fixturePath,[byte[]](1..128))
$candidate=Join-Path $files 'Repato.Revit.dll';$manifest=Join-Path $files 'Repato.addin';$runner=Join-Path $files 'Repato.CreatePlanViews.TestRunner.addin';$policy=Join-Path $files 'MachineWideAddins.allowlist.json'
Set-Content $candidate 'synthetic candidate';Set-Content $manifest 'synthetic build manifest';Set-Content $runner 'synthetic runner';Set-Content $policy '{"schemaVersion":1}'
$candidateHash=(Get-FileHash $candidate -Algorithm SHA256).Hash;$manifestHash=(Get-FileHash $manifest -Algorithm SHA256).Hash;$runnerHash=(Get-FileHash $runner -Algorithm SHA256).Hash;$policyHash=(Get-FileHash $policy -Algorithm SHA256).Hash
$events=[Collections.Generic.List[string]]::new();$prepFiles=$null
try {
  $boot=New-MayaQaBootstrap -StoreRoot $store -QaWorkflowId 'create-plan-views-v1' -RunId 'production-shape-run'
  $task=$boot.TaskId;$workflow=$boot.WorkflowId;$qa='create-plan-views-v1';$null=New-MayaQaBuildRequest -StoreRoot $store -TaskId $task -WorkflowId $workflow -QaWorkflowId $qa -UserRequest 'Create Plan Views' -SourceBranch 'synthetic' -ProjectPath 'synthetic.csproj'
  $d=Read-RepatoTaskStore $store;$t=Find-RepatoTask $d $task;$w=Get-DeployWorkflow $store $task $workflow
  $sourceCommit=('a'*40);$e=[pscustomobject]@{BuildRequestId=$w.qaBuildRequest.BuildRequestId;ArtifactPath=$candidate;ArtifactSha256=$candidateHash;ManifestPath=$manifest;ManifestSha256=$manifestHash;BuildStatus='succeeded';SourceCommit=$sourceCommit;EvidenceSource='Synthetic';CandidateDirectory=$files;CandidateSourceCommit=$sourceCommit;QaWorkflowId=$qa;RunnerManifestPath=$runner;RunnerManifestSha256=$runnerHash;DeployedRunnerManifestPath=$runner;DeployedRunnerManifestSha256=$runnerHash;QaAddinRoot=(Join-Path $files 'RepatoQA');Isolation=[pscustomobject]@{PolicyPath=$policy;PolicySha256=$policyHash;Allowed=$true};DeploymentValidation=$true;ManifestIntegrityValidation=$true;QaIsolation=$true}
  $null=Invoke-RepatoWorkflowMutation $store $task $workflow $w.workflowRevision $t.revision {param($x)$x|Add-Member NoteProperty qaBuildStatus 'succeeded' -Force;$x|Add-Member NoteProperty qaBuildEvidence $e -Force;return $x}
  Invoke-RepatoStoreMutation $store {param($d,$preview)$t=Find-RepatoTask $d $task;$t.status='in-progress';$t.workflowStage='build-checks';foreach($q in @($t.approvalRequests|Where-Object {$_.action -ceq 'qa-run' -and $_.status -ceq 'approved'})){$q.status='rejected';$q.reason='superseded synthetic bootstrap approval'};$w=@($t.deploymentWorkflows|Where-Object workflowId -ceq $workflow)[0];foreach($n in 'qaApprovalId','qaApprovalStatus','qaRunId','qaModelPath','qaSidecarPath','qaFixtureId','qaFixtureSha256','qaTestId','qaFixturePreparationEvidence','qaDisposableModelSha256'){$w.PSObject.Properties.Remove($n)};Add-RepatoHistory $t 'synthetic-fresh-build-checks-state' 'Maya' 'prepare production shape regression';$d}|Out-Null
  New-Item -ItemType Directory -Path $prepRoot -Force|Out-Null;$prepAttempt=[guid]::NewGuid().ToString('N');$prepRunId=[guid]::NewGuid().ToString('N');$fixtureHash=(Get-FileHash $fixturePath -Algorithm SHA256).Hash;$prepModel=Join-Path $prepRoot 'synthetic-prepared-model.rvt';[IO.File]::WriteAllBytes($prepModel,[byte[]](1..96));$prepHash=(Get-FileHash $prepModel -Algorithm SHA256).Hash;$prepRequestPath=Join-Path $prepRoot 'synthetic-preparation.request.json';$prepResultPath=$prepRequestPath+'.preparation.json';$prepRequest=[ordered]@{schemaVersion=1;operation='prepare-disposable-create-plan-views-fixture';requestId=[guid]::NewGuid().ToString('N');taskId=$task;workflowId=$workflow;attemptId=$prepAttempt;runId=$prepRunId;requestPath=$prepRequestPath;modelPath=$prepModel;modelSha256=$fixtureHash;outputPath=$prepResultPath};$prepRequest|ConvertTo-Json -Depth 5|Set-Content -LiteralPath $prepRequestPath -Encoding UTF8;$prepResult=[ordered]@{Status='Passed';Operation='prepare-disposable-create-plan-views-fixture';TaskId=$task;WorkflowId=$workflow;AttemptId=$prepAttempt;RunId=$prepRunId;ModelPath=$prepModel;SourceModelSha256=$fixtureHash;PreparedModelSha256=$prepHash};$prepResult|ConvertTo-Json -Depth 5|Set-Content -LiteralPath $prepResultPath -Encoding UTF8
  $run=New-MayaQaRun -StoreRoot $store -TaskId $task -WorkflowId $workflow -QaWorkflowId $qa -RunId 'production-shape-run' -RuntimeRoot (Join-Path $prepRoot 'runtime') -FixturePreparationResultPath $prepResultPath -ExpectedTaskRevision ([long](Find-RepatoTask (Read-RepatoTaskStore $store) $task).revision);$qaRunRoot=Join-Path $qaRuns ($workflow+'-'+$run.RunId)
  $null=Update-RepatoTask $store $task 'in-progress' 'qa' 'Maya' $null $null -ExpectedTaskRevision ([long]$run.TaskRevision) -ExpectedWorkflowId $workflow -ExpectedWorkflowRevision ([long]$run.WorkflowRevision) -ExpectedQaWorkflowId $qa
  Update-RepatoTask $store $task 'passed' 'qa' 'Tara' $null $null|Out-Null;$null=Request-RepatoTaskApproval $store $task 'qa-run' 'maya';Resolve-RepatoTaskApproval $store $task approve 'Maya' 'synthetic production shape approval'|Out-Null
  $handoff=New-MayaQaCanonicalPreparation -StoreRoot $store -TaskId $task -WorkflowId $workflow -QaWorkflowId $qa
  $d=Read-RepatoTaskStore $store;$t=Find-RepatoTask $d $task;$attempt=$t.mayaTaraAttempt
  foreach($n in 'TaskId','WorkflowId','QaWorkflowId','RunId','AttemptId','RuntimeRoot'){if($attempt.PSObject.Properties.Name -notcontains $n){throw "Persisted attempt missing $n"}}
  $request=[pscustomobject]@{Stage='handoff-ready';TaskId=$task;WorkflowId=$workflow;QaWorkflowId=$qa;RunId=$run.RunId;Handoff=$handoff.Handoff}
  $native={param($s,$id,$claim)$events.Add('native')|Out-Null;$d=Read-RepatoTaskStore $s;$t=Find-RepatoTask $d $id;$r=$t.mayaTaraExecution;if([string]$r.ValidatedRunnerManifestPath -cne [string]$r.RunnerManifestPath){throw "Persisted manifest divergence: runner=[$($r.RunnerManifestPath)] validated=[$($r.ValidatedRunnerManifestPath)]"};New-Item -ItemType Directory -Path $r.DisposableRuntimeRoot -Force -ErrorAction Stop|Out-Null;if(!(Test-Path -LiteralPath $r.DisposableRuntimeRoot -PathType Container)){throw "Synthetic runtime root was not created: $($r.DisposableRuntimeRoot)"};$requestPath=Join-Path $r.DisposableRuntimeRoot ('synthetic-'+$r.RunId+'.request.json');$launcher={param($exe,$args) [pscustomobject]@{Pid=424242;StartedUtc=(Get-Date).ToUniversalTime().ToString('O')}};$result=[pscustomobject]@{TaskId=$r.TaskId;WorkflowId=$r.WorkflowId;QaWorkflowId=$r.QaWorkflowId;TestId=$r.TestId;HandoffId=$r.HandoffId;AttemptId=$r.AttemptId;RunId=$r.RunId;ClaimId=$claim;RequestId=$r.RunId;RequestPath=$requestPath;ResultPath=($requestPath+'.result.json');ReportPath=(Join-Path $r.DisposableRuntimeRoot 'synthetic-report.json');EvidencePath=(Join-Path $r.DisposableRuntimeRoot 'synthetic-evidence.json');EvidenceAccepted=$true;RollbackProven=$true;Verified=$true};Invoke-MayaQaCanonicalNativeCore -StoreRoot $s -TaskId $id -ClaimId $claim -Executable 'synthetic.exe' -Arguments '' -ProcessLauncher $launcher -ManifestValidationBoundary {param($p,$h) $p -ceq $runner -and $h -ceq $runnerHash} -Result $result}
  $tx=Invoke-MayaQaCanonicalTransaction -StoreRoot $store -UserRequest 'Create Plan Views' -RequestInvoker {param($s,$u,$b,$p)$request} -NativeCoreInvoker $native
  $d=Read-RepatoTaskStore $store;$t=Find-RepatoTask $d $task;$execution=$t.mayaTaraExecution
  if($execution.ExecutionStatus -ne 'Completed'){throw "Expected terminal execution, got $($execution.ExecutionStatus)"}
  if($events.Count -ne 1){throw "Expected one injected native boundary, got $($events.Count)"}
  [pscustomobject]@{ProductionShapeHarness='PASS';UsesTemporaryStoreOnly=$true;UsesRealPreparation=$true;UsesRealTransaction=$true;ExecutionRecordCreated=$true;ClaimCreated=$true;NativeRequestSerialized=$true;InjectedNativeBoundary=$true;TerminalBookkeeping=$true;PropertyNotFoundStrictErrors=0;RealStoreMutated=$false;RevitLaunched=$false}|ConvertTo-Json -Compress
} finally { if([IO.Path]::GetFullPath($isolatedRoot).StartsWith($tempBase,[StringComparison]::OrdinalIgnoreCase) -and (Test-Path -LiteralPath $isolatedRoot)){Remove-Item -LiteralPath $isolatedRoot -Recurse -Force -ErrorAction SilentlyContinue} }
